from pathlib import Path
import bpy,numpy as np,json,time,hashlib
from mathutils import Vector
R=Path('D:/Download/Aevrynd');E=R/'Evidence/character-female-next/r0130-artist-native-groom';S=R/'engine/assets/characters/female-next/source/r0130-source';SRC=S/'artist-original-ellie-restored-native-groom.blend';OUT=S/'artist-original-ellie-native-curve-reference.blend'
def save(n,x):(E/n).write_text(json.dumps(x,indent=2,default=lambda x:x.tolist() if isinstance(x,np.ndarray) else x.item())+'\n',encoding='utf-8')
def arr(c,k,n,w=3,dt='f4'):
 a=np.empty((n,w),dt);c.foreach_get(k,a.ravel());return a
def main():
 tick=time.time();assert not OUT.exists();bpy.ops.wm.open_mainfile(filepath=str(SRC));scalp=bpy.data.objects['GEO-ellie_hair_cut.scalp'];bpy.context.scene.frame_set(1)
 for ps in scalp.particle_systems:ps.settings.child_percent=ps.settings.rendered_child_count
 scalp.hide_render=False;scalp.hide_set(False);bpy.context.view_layer.update();dg=bpy.context.evaluated_depsgraph_get();ev=scalp.evaluated_get(dg);A=np.array(scalp.matrix_world);raws=[];counts=[];guides=[];gc=[];regions=[];rows=[]
 for ps in ev.particle_systems:
  md=next(m for m in ev.modifiers if m.type=='PARTICLE_SYSTEM' and m.particle_system.name==ps.name);base=scalp.particle_systems[ps.name];proxy=bpy.data.objects[scalp.name+'-'+ps.name].evaluated_get(dg);Q=arr(proxy.data.vertices,'co',len(proxy.data.vertices));G=np.array([k.co_object(ev,md,p)[:] for p in ps.particles for k in p.hair_keys]);error=float(np.linalg.norm(G-Q[:len(G)],axis=1).max());assert error<2e-5,(ps.name,error);guides.append(G@A[:3,:3].T+A[:3,3]);gc.extend([len(p.hair_keys) for p in ps.particles]);N=2**ps.settings.display_step+1;raw=np.array([[ps.co_hair(ev,particle_no=i,step=j)[:] for j in range(N)] for i in range(len(ps.particles)+len(ps.child_particles))],dtype='f4');n=np.any(raw!=0,axis=2).sum(1);valid=np.arange(N)[None,:]<n[:,None];assert np.isfinite(raw).all() and np.all(n>=2) and np.all(raw[~valid]==0) and np.all(np.any(raw[valid]!=0,axis=1)),(ps.name,n.min(),n.max());raws.append(raw[valid]);counts.extend(n.tolist());regions.extend([ps.name]*len(n));rows.append({'system':ps.name,'parents':len(ps.particles),'children':len(ps.child_particles),'pathSlots':N,'validCountRange':[int(n.min()),int(n.max())],'originalKeysPersistedAfterIndependentReopenMaxSourceUnits':error,'renderType':ps.settings.render_type,'originalRadiusScale':ps.settings.radius_scale,'originalRootRadius':ps.settings.root_radius,'cacheSamplingNotExactRendererInterpolation':True})
 P=np.concatenate(raws);counts=np.array(counts,'i4');G=np.concatenate(guides);gc=np.array(gc,'i4');cap=scalp.data.copy();cap.calc_loop_triangles();capV=arr(cap.vertices,'co',len(cap.vertices))@A[:3,:3].T+A[:3,3];capT=arr(cap.loop_triangles,'vertices',len(cap.loop_triangles),3,'i4');head=bpy.data.objects['GEO-ellie_head'];hd=head.evaluated_get(dg).data;H=arr(hd.vertices,'co',len(hd.vertices));HA=np.array(head.matrix_world);H=H@HA[:3,:3].T+HA[:3,3];hd.calc_loop_triangles();HT=arr(hd.loop_triangles,'vertices',len(hd.loop_triangles),3,'i4');np.savez_compressed(E/'original-native-studio-cache.npz',world=P,counts=counts,guideWorld=G,guideCounts=gc,capWorld=capV,capTriangles=capT,headWorld=H,headTriangles=HT,sourceRegions=np.array(regions))
 s=bpy.data.scenes.new('AFN130_ISOLATED_SOURCE_NATIVE_CURVE_REFERENCE');bpy.context.window.scene=s;mesh=bpy.data.meshes.new('AFN130_ORIGINAL_STUDIO_HEAD_REFERENCE');mesh.from_pydata(H.tolist(),[],HT.tolist());mesh.update();ho=bpy.data.objects.new(mesh.name,mesh);s.collection.objects.link(ho)
 for f in mesh.polygons:f.use_smooth=True
 clay=bpy.data.materials.new('AFN130_ISOLATED_REFERENCE_CLAY');clay.use_nodes=True;clay.node_tree.nodes.clear();cp=clay.node_tree.nodes.new('ShaderNodeBsdfPrincipled');cp.inputs['Base Color'].default_value=(.25,.25,.25,1);co=clay.node_tree.nodes.new('ShaderNodeOutputMaterial');clay.node_tree.links.new(cp.outputs[0],co.inputs[0]);mesh.materials.append(clay)
 d=bpy.data.hair_curves.new('AFN130_ORIGINAL_STUDIO_NATIVE_CACHE_CURVES');d.add_curves(counts.tolist());d.position_data.foreach_set('vector',P.ravel());rad=d.attributes.new('radius','FLOAT','POINT');radius=np.concatenate([.000045*(1-.95*np.linspace(0,1,int(n))**4) for n in counts]);rad.data.foreach_set('value',radius.astype('f4'));hair=bpy.data.objects.new(d.name,d);s.collection.objects.link(hair);mat=bpy.data.materials['AFN130_OWN_REFERENCE_DARK_BROWN_NATIVE_HAIR'];d.materials.append(mat)
 s.render.engine='CYCLES';s.cycles.samples=16;s.cycles.use_denoising=True;s.render.threads_mode='FIXED';s.render.threads=4;s.render.resolution_x=s.render.resolution_y=640;s.render.resolution_percentage=100;s.render.image_settings.file_format='PNG';s.render.hair_subdiv=3;s.view_settings.view_transform='AgX';s.view_settings.look='AgX - Medium High Contrast';s.view_settings.exposure=-.5;s.world=bpy.data.worlds['AFN130_SOURCE_REFERENCE_WORLD'];span=H[:,2].max()-H[:,2].min();aim=(H.min(0)+H.max(0))*.5;distance=span*3.;cd=bpy.data.cameras.new('AFN130_ISOLATED_NATIVE_CAMERA');camera=bpy.data.objects.new(cd.name,cd);s.collection.objects.link(camera);s.camera=camera;cd.lens=60
 for name,off,power,size in [('KEY',[-1.2,-1.5,1.8],600,1.3),('FILL',[1.4,-1.1,.8],300,1.8),('RIM',[.5,1.2,1.5],500,1.0)]:
  ld=bpy.data.lights.new('AFN130_ISOLATED_'+name,'AREA');ld.energy=power*span*span;ld.shape='DISK';ld.size=size*span;lo=bpy.data.objects.new(ld.name,ld);s.collection.objects.link(lo);lo.location=Vector(aim+np.array(off)*span);lo.rotation_euler=(Vector(aim)-lo.location).to_track_quat('-Z','Y').to_euler()
 save('original-native-studio-cache-readback.json',{'source':str(SRC),'sourceSha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'systems':rows,'curves':len(counts),'points':len(P),'allSourceParentsChildrenAndValidCacheKnotsRetained':True,'originalProxyKeyCounts':gc.tolist(),'originalCapVertices':len(capV),'originalCapTriangles':len(capT),'originalCapAndRestoredKeysPreserved':True,'isolatedSceneContainsOnlySourceHeadAndNewNativeCurves':True,'initialNewPhysicalCurveRootRadiusM':.000045,'newRadiusIsUncalibratedEngineeringChoiceNotOriginalRendererRadius':True,'noDensityShapeClumpRadiusOrMaterialSweep':True,'notCurrentWomanOrAcceptedGain':True,'secondsBeforePreview':time.time()-tick})
 bpy.context.preferences.filepaths.save_version=0;bpy.ops.wm.save_as_mainfile(filepath=str(OUT),compress=True)
 for name,off in [('face',[0,-distance,.1*span]),('profile',[-distance,0,.1*span])]:camera.location=Vector(aim+np.array(off));camera.rotation_euler=(Vector(aim)-camera.location).to_track_quat('-Z','Y').to_euler();s.render.filepath=str(E/('reference-isolated-native-ellie-'+name+'.png'));bpy.ops.render.render(write_still=True)
 save('original-native-curve-reference-source.json',{'source':str(OUT),'sha256':hashlib.sha256(OUT.read_bytes()).hexdigest(),'bytes':OUT.stat().st_size,'referenceOnly':True});print('R130_ORIGINAL_NATIVE_STUDIO_CURVE_REFERENCE_DONE',time.time()-tick,flush=True)
if __name__=='__main__':main()
